import numpy as np
from scipy.optimize import minimize_scalar

def c(a,b):
    if abs(a-b)<1e-14: return 1/a
    return (np.log(a)-np.log(b))/(a-b)

def Rperp_u(u,g):
    # s0/s1 = u ; Rperp = (1-g) c(t0,t1)/c(s0,s1), t0/t1=(u+g)/(1-g)
    s0,s1 = u/(1+u), 1/(1+u)
    t0,t1 = s0+g*s1, (1-g)*s1
    return (1-g)*c(t0,t1)/c(s0,s1)

def Rz_u(u,g):
    s0,s1 = u/(1+u), 1/(1+u)
    t0,t1 = s0+g*s1, (1-g)*s1
    return (1-g)**2*s0*s1/(t0*t1)

for g in [0.125,0.25,0.5]:
    r1=minimize_scalar(lambda u:-Rperp_u(u,g),bounds=(1e-12,1e12),method='bounded',options={'xatol':1e-16})
    r2=minimize_scalar(lambda u:-Rz_u(u,g),bounds=(1e-12,1e12),method='bounded',options={'xatol':1e-16})
    f=max(-r1.fun,-r2.fun)
    z=(r1.x-1)/(r1.x+1)
    print(f'g={g}: Rperp max={-r1.fun:.12f} at u={r1.x:.6f} z={z:.6f}; Rz max={-r2.fun:.12f}; f={f:.12f}')
