import numpy as np

def c(a,b):
    if abs(a-b)<1e-14: return 1/a
    return (np.log(a)-np.log(b))/(a-b)

def metric_inner(X, tau):
    # <X, Omega_tau"'^{-1}(X)> = sum_ij |X_ij|''^2 c(l_i,l_j) in tau eigenbasis
    e,U=np.linalg.eigh(tau)
    Xb=U.conj().T@X@U
    out=0.0
    for i in range(2):
        for j in range(2):
            out+=abs(Xb[i,j])**2*c(e[i],e[j])
    return np.real(out)

def A(rho,g):
    return np.array([[rho[0,0]+g*rho[1,1],np.sqrt(1-g)*rho[0,1]],[np.sqrt(1-g)*rho[1,0],(1-g)*rho[1,1]]])

g=0.25
for s in [0.5,0.7727,0.95]:
    best=(0,None)
    for th in np.linspace(0,np.pi/2,46):
        n=np.array([np.sin(th),0,np.cos(th)])
        # tau eigenbasis: |0'"'> = cos(th/2)|0>+sin(th/2)|1>
        U=np.array([[np.cos(th/2),-np.sin(th/2)],[np.sin(th/2),np.cos(th/2)]])
        tau=U@np.diag([(1+s)/2,(1-s)/2])@U.T
