from itertools import permutations, product

def perm_mul(a,b): # a*b means apply b then a; tuple product
    return tuple(a[b[i]] for i in range(len(a)))

def perm_inv(a):
    inv=[0]*len(a)
    for i,x in enumerate(a): inv[x]=i
    return tuple(inv)

def cycles(a):
    n=len(a); seen=[False]*n; lens=[]
    for i in range(n):
        if not seen[i]:
            j=i; L=0
            while not seen[j]:
                seen[j]=True; j=a[j]; L+=1
            lens.append(L)
    return sorted(lens, reverse=True)

def dist(a):
    return len(a)-len(cycles(a))

def catalan(k):
    from math import comb
    return comb(2*k,k)//(k+1)

def f(a):
    import math
    out=1
    for L in cycles(a): out*=catalan(L)
    return out

def brute(n):
    e=tuple(range(n)); c=tuple((i+1)%n for i in range(n))
    perms=list(permutations(range(n)))
    le=[p for p in perms if dist(p)+dist(perm_mul(perm_inv(p),c))==dist(c)]
    total=0
    triples=0
    # sum over coarse X,H,Z with c=XHZ minimal
    for X in le:
      rem1=perm_mul(perm_inv(X),c)
      for H in [h for h in le if dist(h)+dist(perm_mul(perm_inv(h),rem1))==dist(rem1)]:
        Z=perm_mul(perm_inv(H),rem1)
        if dist(X)+dist(H)+dist(Z)==dist(c):
          weight=f(X)*f(H)**2*f(Z)
          total += weight
          triples += 1
    return total, len(le), triples
for n in range(1,6):
    print(n, brute(n))
