import numpy as np
from math import log2

def h2(z):
    if z <= 0 or z >= 1:
        return 0.0
    return -z*log2(z)-(1-z)*log2(1-z)

def H(v):
    v=np.array(v,dtype=float); v=v[v>1e-14]
    return float(-(v*np.log2(v)).sum())

def rho(g,phi,t):
    c=np.sqrt(t); s=np.sqrt(1-t)
    return np.array([[g*t,0,0],[0,(1-g)*t,c*s*np.sqrt(1-g)*np.exp(1j*phi)],[0,c*s*np.sqrt(1-g)*np.exp(-1j*phi),1-t]],complex)

def chi(ens,t):
    avg=sum(p*rho(g,ph,t) for p,g,ph in ens)
    return H(np.linalg.eigvalsh(avg))-sum(p*H(np.linalg.eigvalsh(rho(g,ph,t))) for p,g,ph in ens)

rng=np.random.default_rng(4)
for t in [0.05,0.2,0.5,0.8,0.99]:
    pred=h2(t)+t*log2(1+2**(-h2(t)/t))
    best=0
    for _ in range(2000):
        n=4
        p=rng.random(n); p/=p.sum()
        g=rng.random(n); ph=rng.uniform(0,2*np.pi,n)
        best=max(best,chi(list(zip(p,g,ph)),t))
    print(t, 'random best', best, 'formula', pred, 'gap', pred-best)
PY"

