import numpy as np, itertools, sys
from proto3 import run

N = int(sys.argv[1])
beta = {}
for ks in itertools.product(range(N), repeat=4):
    C, qs, qsf = run(N, *ks)
    di = np.diag(C)
    ph = np.angle(di)/np.pi
    if 0 in qs:
        beta[ks] = ph[qs.index(0)]

# print beta(0,k23,k12,k13) as matrix rows=k12, cols=k13 for each k23
print(f\"N={N}  beta/pi (k34=0), rows k12, cols k13:\")
for k23 in range(N):
    print(f\" k23={k23}:\")
    for k12 in range(N):
        row = \"   \"
        for k13 in range(N):
            v = beta.get((0,k23,k12,k13), float('nan'))
            row += f\"{v:+.3f} \"
        print(row)
# verify k34 independence
print(\"k34 dependence check (max |beta(k34)-beta(0)|):\")
for k23 in range(N):
    for k12 in range(N):
        for k13 in range(N):
            vals=[beta.get((k34,k23,k12,k13)) for k34 in range(N)]
            vals=[v for v in vals if v is not None]
            if len(vals)>1:
                # account mod 2
                d=max(abs((v-vals[0]+1)%2-1) for v in vals)
                if d>0.05: print(f\"  k23={k23},k12={k12},k13={k13}: spread {d:.3f} vals={np.round(vals,3)}\")
print(\"done\")
