import numpy as np, itertools
from proto3 import run as run3

def model(ks,q,N):
    k34,k23,k12,k13=ks
    return (-(2*np.pi/N)*q + (2*np.pi/N)*((k23-k12-k13)%N))

f=0;t=0;checked=0
for ks in itertools.product(range(3),repeat=4):
    C,qs,_=run3(3,*ks)
    di=np.diag(C); off=np.abs(C-np.diag(di)).max()
    if off>1e-6: continue
    checked+=1
    ph=np.angle(di)
    # use q=0 (always present) for beta; and full set if nondegenerate
    d={}
    for q,p in zip(qs,ph): d.setdefault(q,p)
    for q,p in d.items():
        t+=1; pred=model(ks,q,3)
        dd=(p-pred+np.pi)%(2*np.pi)-np.pi
        if abs(dd)>0.05: f+=1; print(f\"  MISMATCH k={ks} q={q} num={p/np.pi:+.2f} pred={(pred/np.pi)%2:+.2f}\")
print(f\"N=3: {checked} clean configs, {t} channel pts, {f} mismatches\")
EOF
